        return f'{self.name} has a population of {self.population} and {self.deaths} deaths.'

class Threat:
    def __init__(self, name, impact):
        self.name = name
        self.impact = impact

    def __str__(self):
        return f'{self.name} has an impact of {self.impact}.'

class Simulation:
    def __init__(self, city, threats):
        self.city = city
        self.threats = threats

    def run(self):
        for threat in self.threats:
            self.city.deaths += self.city.population * threat.impact / 100
        print(self.city)

def main():
    city = City('New York', 1000000)
    threats = [
        Threat('Tornado', 10),
        Threat('Earthquake', 20),
        Threat('Hurricane', 30),
        Threat('Pandemic', 40),
        Threat('Nuclear War', 100)
    ]
    simulation = Simulation(city, threats)
    simulation.run()

if __name__ == "__main__":
    main()
```

