import os
import time
import random

class Virus:
    def __init__(self, name):
        self.name = name
        self.host = None
        self.replication_rate = 0.5
        self.kill_rate = 0.1
        self.recovery_rate = 0.2

    def infect(self, host):
        self.host = host
        print(f"{self.name} has infected {host}!")

    def replicate(self):
        if random.random() < self.replication_rate:
            print(f"{self.name} is replicating...")
            self.host = None
            return True
        return False

    def kill(self):
        if random.random() < self.kill_rate:
            print(f"{self.name} has killed {self.host}!")
            return True
        return False

    def recover(self):
        if random.random() < self.recovery_rate:
            print(f"{self.host} has recovered from {self.name}!")
            return True
        return False

    def spread(self):
        if self.host is not None:
            self.host = None
            return True
        return False

    def run(self):
        while True:
            if self.host is not None:
                if self.replicate():
                    self.spread()
                elif self.kill():
                    self.host = None
                elif self.recover():
                    self.host = None
            time.sleep(1)

def main():
    virus = Virus("Computer Virus")
    virus.run()

if __name__ == "__main__":
    main()
```
